# Problem: validate balanced bracket string.
# Stack-based: push openers, pop on matching closer; reject mismatch or unbalanced state.
def is_valid_parens(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for c in s:
        if c in '([{':
            stack.append(c)  # opener: remember
        elif c in ')]}':
            if not stack or stack[-1] != pairs[c]:
                return False  # closer without matching opener
            stack.pop()
    return not stack  # stack must be empty when done
```

