# Problem: 4-connected reachability in a grid.
# DFS with explicit stack and visited set. Skip blocked or out-of-bounds neighbours.
def has_path(grid, sr, sc, er, ec):
    R, C = len(grid), len(grid[0])
    if grid[sr][sc] == '#' or grid[er][ec] == '#':
        return False  # start or end blocked: no path
    seen = {(sr, sc)}
    stack = [(sr, sc)]
    while stack:
        r, c = stack.pop()
        if (r, c) == (er, ec):
            return True  # reached target
        for dr, dc in ((-1,0), (1,0), (0,-1), (0,1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == '.' and (nr, nc) not in seen:
                seen.add((nr, nc))
                stack.append((nr, nc))
    return False
```

