# Problem: group strings by anagram equivalence (same multiset of letters).
# Canonical signature: sorted characters. Hash-map by signature; values are the groups.
def group_anagrams(strs):
    from collections import defaultdict
    groups = defaultdict(list)
    for s in strs:
        groups[''.join(sorted(s))].append(s)  # key = sorted letters
    return list(groups.values())
```

