# Problem: list every starting index of pattern in text (non-overlapping not required).
# Simple sliding compare; for n, m small enough this is fine.
def find_occurrences(text, pattern):
    if not pattern:
        return []
    result = []
    m = len(pattern)
    for i in range(len(text) - m + 1):
        if text[i:i + m] == pattern:
            result.append(i)
    return result
```

