# Problem: detect tree symmetry (mirror property around the root).
# Symmetry is a pairwise property: left subtree's left mirrors right subtree's right.
# Helper compares two nodes; recurses on outer/outer + inner/inner pairs.
def is_symmetric(root):
    def mirror(a, b):
        if not a and not b:  # both null = symmetric base case
            return True
        if not a or not b:  # one null, one not = asymmetric
            return False
        return a.val == b.val and mirror(a.left, b.right) and mirror(a.right, b.left)
    if not root:
        return True
    return mirror(root.left, root.right)
```
